-- ── ROUTE_COST (1284건) ─────────────────────────────────────────

MERGE INTO ROUTE_COST T
USING (SELECT '1200' AS SHPPT, '01-A01' AS ROUTE, '209616' AS PTNRKY, 'Z010' AS CARCLASS, '248700.0' AS COST, 'KRW' AS UNIT, '20250101' AS DATE_START, '99991231' AS DATE_END, '20260625' AS CREDAT, '052010' AS CRETIM, 'ADMIN' AS CREUSR, '20260625' AS LMODAT, '052010' AS LMOTIM, 'ADMIN' AS LMOUSR FROM DUAL) S
ON (T.ROUTE = S.ROUTE AND T.PTNRKY = S.PTNRKY AND T.CARCLASS = S.CARCLASS)
WHEN MATCHED THEN
    UPDATE SET T.SHPPT = S.SHPPT, T.COST = S.COST, T.UNIT = S.UNIT, T.DATE_START = S.DATE_START, T.DATE_END = S.DATE_END, T.LMODAT = S.LMODAT, T.LMOTIM = S.LMOTIM, T.LMOUSR = S.LMOUSR
WHEN NOT MATCHED THEN
    INSERT (SHPPT, ROUTE, PTNRKY, CARCLASS, COST, UNIT, DATE_START, DATE_END, CREDAT, CRETIM, CREUSR, LMODAT, LMOTIM, LMOUSR)
    VALUES (S.SHPPT, S.ROUTE, S.PTNRKY, S.CARCLASS, S.COST, S.UNIT, S.DATE_START, S.DATE_END, S.CREDAT, S.CRETIM, S.CREUSR, S.LMODAT, S.LMOTIM, S.LMOUSR);

